# Detect SWITCH statements missing default branch
# A SWITCH is considered missing default if:
# - It has type SWITCH (2)
# - It has at least 2 branches in the else_statement chain
# - No branch in the chain has is_default=true
# - It's a top-level SWITCH (is_top=true) or nested in another SWITCH

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find all ConditionalStatements in the tree
    walk(parent, [_, node])

    node.ir_type == "ConditionalStatement"
    node.type == 2  # SWITCH
    node.is_top == true

    # Must have at least 2 branches (count nodes in else_statement chain)
    count_chain_length(node) >= 2

    # No default branch in the chain
    not has_default_in_chain(node)

    result := {
        "type": "sec_no_default_switch",
        "element": node,
        "path": parent.path,
        "description": "Missing default case in multi-condition construct - Add a default/fallback branch to handle unexpected values. (CWE-478)"
    }
}

